cond distinct key)', 'cases': [{'input': [{'parameter': 'schemaUri', 'value': 'new TestSchemaLocation("http://example.com/schema3")'}, {'parameter': 'config', 'value': 'new SchemaValidatorsConfig()'}], 'expected': 'The method invokes getMappedSchema() for the new key, stores it in the cache, calls withConfig(config) and returns the configured schema.', 'description': 'When a different SchemaLocation is requested, even with caching enabled, the cache should miss for that key and behave like the first‑miss scenario.'}]}, {'group': 'Null SchemaLocation – Cache Disabled', 'cases': [{'input': [{'parameter': 'schemaUri', 'value': 'null'}, {'parameter': 'config', 'value': 'new SchemaValidatorsConfig()'}], 'expected': 'NullPointerException is thrown because schemaUri is null and the method attempts to use it as a key for the cache/computed lookup.', 'description': 'When caching is disabled the method does not guard against a null SchemaLocation; passing null should result in an immediate NPE.'}]}, {'group': 'Null SchemaLocation – Cache Enabled', 'cases': [{'input': [{'parameter': 'schemaUri', 'value': 'null'}, {'parameter': 'config', 'value': 'new SchemaValidatorsConfig()'}], 'expected': 'NullPointerException is thrown because the null key cannot be used with ConcurrentMap.computeIfAbsent.', 'description': 'With caching enabled the lambda passed to computeIfAbsent receives a null key, which should cause an NPE.'}]}, {'group': 'Null Config Parameter', 'cases': [{'input': [{'parameter': 'schemaUri', 'value': 'new TestSchemaLocation("http://example.com/schema-null-config")'}, {'parameter': 'config', 'value': 'null'}], 'expected': 'NullPointerException is thrown when withConfig(null) is invoked on the cached/raw JsonSchema.', 'description': 'The factory always calls withConfig on the schema; passing a null config should cause an NPE (the real implementation validates the argument).'}]}, {'group': 'Exception Propagation from getMappedSchema', 'cases': [{'input': [{'parameter': '